const treino = [
  { exercicio: 'Agachamento', series: 4 },
  { exercicio: 'Supino', series: 3 },
  { exercicio: 'Remada', series: 2 },
];

const soma = treino[0].series + treino[1].series + treino[2].series;

console.log('Exercícios:', treino.length);
console.log('Primeiro:', treino[0].exercicio);
console.log('Último:', treino[2].exercicio);
console.log('Média de séries:', soma / treino.length);
